create or replace package body margin_report as
  function margin_pct(p_sku in varchar2) return number is
    l_margin number;
  begin
    select round((i.list_price - avg_cost) / i.list_price * 100, 1)
      into l_margin
      from (
        select i.list_price, average_unit_cost(i.sku) as avg_cost
        from item_margins_v i
        where i.sku = p_sku
      )
      where 1=1;
    return l_margin;
  end margin_pct;
end margin_report;
/

